// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount, uint256 wait) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        unlockTime = bound(unlockTime, 1, 1_000_000);
        amount = bound(amount, 1, 1e24);
        wait = bound(wait, 0, 1_000_000);

        RecordingAsset asset = new RecordingAsset();

        // DAO not yet configured, so proposal-gated setters are open to anyone.
        c.configureFlashGovernance(address(asset), amount, unlockTime, false);

        address[] memory gov = new address[](1);
        gov[0] = actor;
        bool[] memory flags = new bool[](1);
        flags[0] = true;
        c.setGoverned(gov, flags);

        // actor makes the flash-governance deposit, unlocking at block.timestamp + unlockTime
        vm.prank(actor);
        c.assertGovernanceApproved(actor, actor, false);

        // advance past the unlock time: withdrawal must now succeed
        vm.warp(block.timestamp + unlockTime + wait + 1);

        vm.prank(actor);
        bool ok;
        try c.withdrawGovernanceAsset(actor, address(asset)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && asset.sentTo(address(actor)) && asset.sentAmount() == amount);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}

contract RecordingAsset {
    mapping(address => bool) public sentTo;
    uint256 public sentAmount;

    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address to, uint256 amount) external returns (bool) {
        sentTo[to] = true;
        sentAmount = amount;
        return true;
    }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
}
